		const item = fetchItemStatic(ref);
		if (!item) {
			throw new Error(`Item not found: ${ref}`);
		}
		return item;
	}

	const response = await fetch(`${API_BASE}/api/items/${ref}`, {
		headers: getProjectHeaders()
