/**
 * Fetch inbox items
 * AC: @web-dashboard ac-16
 * AC: @multi-directory-daemon ac-26 - Includes X-Kspec-Dir header
 * AC: @gh-pages-export ac-11 - Static mode support
 */
export async function fetchInbox(params?: {
	limit?: number;
	offset?: number;
