     1→/**
     2→ * Task API Routes
     3→ *
     4→ * REST endpoints for task operations:
     5→ * - GET /api/tasks - list with filters and pagination
     6→ * - GET /api/tasks/:ref - get single task
     7→ * - POST /api/tasks/:ref/start - start task
     8→ * - POST /api/tasks/:ref/note - add note
     9→ *
    10→ * AC Coverage:
    11→ * - ac-2: GET /api/tasks returns array with status, priority, spec_ref, notes count
    12→ * - ac-3: Status filter with multi-value support
    13→ * - ac-4: Pagination with {items, total, offset, limit} wrapper
    14→ * - ac-5: GET /api/tasks/:ref resolves via ReferenceIndex
    15→ * - ac-6: POST /api/tasks/:ref/start transitions state
    16→ * - ac-7: POST /api/tasks/:ref/note appends note
    17→ */
    18→
    19→import { Elysia, t } from 'elysia';
    20→import {
    21→  initContext,
    22→  loadAllTasks,
    23→  loadAllItems,
    24→  ReferenceIndex,
    25→  createNote,
    26→  saveTask,
    27→  getAuthor,
    28→  syncSpecImplementationStatus,
    29→  type LoadedTask,
    30→} from '../../parser/index.js';
    31→import { commitIfShadow } from '../../parser/shadow.js';
    32→import type { PubSubManager } from '../websocket/pubsub';
    33→
    34→interface TasksRouteOptions {
    35→  pubsub: PubSubManager;
    36→}
    37→
    38→export function createTasksRoutes(options: TasksRouteOptions) {
    39→  const { pubsub } = options;
    40→
    41→  return new Elysia({ prefix: '/api/tasks' })
    42→    // AC: @api-contract ac-2, ac-3, ac-4 - List tasks with filters and pagination
    43→    .get(
    44→      '/',
    45→      async ({ query, projectContext }) => {
    46→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
    47→        const ctx = await initContext(projectContext.path);
    48→        const tasks = await loadAllTasks(ctx);
    49→        const specItems = await loadAllItems(ctx);
    50→        const index = new ReferenceIndex(tasks, specItems);
    51→
    52→        // Apply filters
    53→        let filtered = tasks;
    54→
    55→        // AC: @api-contract ac-3 - Multi-value status filter
    56→        if (query.status) {
    57→          const statusFilters = Array.isArray(query.status) ? query.status : [query.status];
    58→          filtered = filtered.filter((task) => statusFilters.includes(task.status));
    59→        }
    60→
    61→        // Type filter (optional, not in ACs but useful)
    62→        if (query.type) {
    63→          const typeFilters = Array.isArray(query.type) ? query.type : [query.type];
    64→          filtered = filtered.filter((task) => task.type && typeFilters.includes(task.type));
    65→        }
    66→
    67→        // Tag filter (optional, not in ACs but useful)
    68→        if (query.tag) {
    69→          const tagFilters = Array.isArray(query.tag) ? query.tag : [query.tag];
    70→          filtered = filtered.filter((task) =>
    71→            task.tags?.some((t) => tagFilters.includes(t))
    72→          );
    73→        }
    74→
    75→        // AC: @api-contract ac-4 - Pagination
    76→        const total = filtered.length;
    77→        const offset = Number(query.offset) || 0;
    78→        const limit = Number(query.limit) || total;
    79→
    80→        const paginated = filtered.slice(offset, offset + limit);
    81→
    82→        // AC: @api-contract ac-2 - Return with status, priority, spec_ref, notes count
    83→        // AC: @web-dashboard ac-1 - Include depends_on for blocked task computation
    84→        const items = paginated.map((task) => ({
    85→          _ulid: task._ulid,
    86→          slugs: task.slugs,
    87→          title: task.title,
    88→          status: task.status,
    89→          priority: task.priority,
    90→          spec_ref: task.spec_ref,
    91→          meta_ref: task.meta_ref,
    92→          tags: task.tags,
    93→          depends_on: task.depends_on || [],
    94→          notes_count: task.notes?.length || 0,
    95→          todos_count: task.todos?.length || 0,
    96→          started_at: task.started_at,
    97→          completed_at: task.completed_at,
    98→          created_at: task.created_at,
    99→        }));
   100→
   101→        // AC: @api-contract ac-4, @trait-api-endpoint ac-4 - Return pagination wrapper
   102→        return {
   103→          items,
   104→          total,
   105→          offset,
   106→          limit,
   107→        };
   108→      },
   109→      {
   110→        query: t.Object({
   111→          status: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   112→          type: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   113→          tag: t.Optional(t.Union([t.String(), t.Array(t.String())])),
   114→          limit: t.Optional(t.String()),
   115→          offset: t.Optional(t.String()),
   116→        }),
   117→      }
   118→    )
   119→
   120→    // AC: @api-contract ac-5 - Get single task by ref
   121→    .get(
   122→      '/:ref',
   123→      async ({ params, error: errorResponse, projectContext }) => {
   124→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   125→        const ctx = await initContext(projectContext.path);
   126→        const tasks = await loadAllTasks(ctx);
   127→        const items = await loadAllItems(ctx);
   128→        const index = new ReferenceIndex(tasks, items);
   129→
   130→        // AC: @api-contract ac-5, @trait-api-endpoint ac-2 - Resolve ref via ReferenceIndex
   131→        const result = index.resolve(params.ref);
   132→
   133→        if (!result.ok) {
   134→          // AC: @trait-api-endpoint ac-2 - Return 404 with error details
   135→          return errorResponse(404, {
   136→            error: 'not_found',
   137→            message: `Task reference "${params.ref}" not found`,
   138→            suggestion: 'Use kspec task list or kspec search to find valid task references',
   139→          });
   140→        }
   141→
   142→        // Find the task
   143→        const task = tasks.find((t) => t._ulid === result.ulid);
   144→        if (!task) {
   145→          return errorResponse(404, {
   146→            error: 'not_found',
   147→            message: `Reference "${params.ref}" is not a task`,
   148→            suggestion: 'This reference might point to a spec item instead',
   149→          });
   150→        }
   151→
   152→        // AC: @api-contract ac-5 - Return full task with notes, todos, dependencies
   153→        return {
   154→          _ulid: task._ulid,
   155→          slugs: task.slugs,
   156→          title: task.title,
   157→          status: task.status,
   158→          priority: task.priority,
   159→          spec_ref: task.spec_ref,
   160→          meta_ref: task.meta_ref,
   161→          tags: task.tags,
   162→          description: task.description,
   163→          depends_on: task.depends_on,
   164→          notes: task.notes,
   165→          todos: task.todos,
   166→          started_at: task.started_at,
   167→          completed_at: task.completed_at,
   168→          cancelled_at: task.cancelled_at,
   169→          closed_reason: task.closed_reason,
   170→          automation: task.automation,
   171→          created_at: task.created_at,
   172→        };
   173→      },
   174→      {
   175→        params: t.Object({
   176→          ref: t.String(),
   177→        }),
   178→      }
   179→    )
   180→
   181→    // AC: @api-contract ac-6 - Start task
   182→    .post(
   183→      '/:ref/start',
   184→      async ({ params, error: errorResponse, projectContext }) => {
   185→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   186→        const ctx = await initContext(projectContext.path);
   187→        const tasks = await loadAllTasks(ctx);
   188→        const items = await loadAllItems(ctx);
   189→        const index = new ReferenceIndex(tasks, items);
   190→
   191→        // Resolve ref
   192→        const result = index.resolve(params.ref);
   193→        if (!result.ok) {
   194→          return errorResponse(404, {
   195→            error: 'not_found',
   196→            message: `Task reference "${params.ref}" not found`,
   197→            suggestion: 'Use kspec task list to find valid task references',
   198→          });
   199→        }
   200→
   201→        const task = tasks.find((t) => t._ulid === result.ulid);
   202→        if (!task) {
   203→          return errorResponse(404, {
   204→            error: 'not_found',
   205→            message: `Reference "${params.ref}" is not a task`,
   206→          });
   207→        }
   208→
   209→        // AC: @api-contract ac-6 - Transition to in_progress
   210→        if (task.status === 'in_progress') {
   211→          return errorResponse(409, {
   212→            error: 'invalid_transition',
   213→            message: 'Task is already in_progress',
   214→            current: task.status,
   215→            valid_transitions: ['blocked', 'pending_review', 'completed', 'cancelled'],
   216→          });
   217→        }
   218→
   219→        // Update task status
   220→        const updatedTask: LoadedTask = {
   221→          ...task,
   222→          status: 'in_progress',
   223→          started_at: task.started_at || new Date().toISOString(),
   224→        };
   225→
   226→        // Save and commit
   227→        await saveTask(ctx, updatedTask);
   228→        await syncSpecImplementationStatus(ctx, updatedTask, tasks, items, index);
   229→        await commitIfShadow(ctx.shadow, `task: start ${params.ref}`);
   230→
   231→        // AC: @api-contract ac-6, @trait-api-endpoint ac-5 - WebSocket broadcast
   232→        // AC: @multi-directory-daemon ac-18 - Broadcast scoped to request project
   233→        pubsub.broadcast('tasks:updates', 'task_updated', {
   234→          ref: params.ref,
   235→          ulid: task._ulid,
   236→          action: 'start',
   237→          status: 'in_progress',
   238→        }, projectContext.path);
   239→
   240→        // AC: @api-contract ac-6 - Return updated task
   241→        return updatedTask;
   242→      },
   243→      {
   244→        params: t.Object({
   245→          ref: t.String(),
   246→        }),
   247→      }
   248→    )
   249→
   250→    // AC: @api-contract ac-7 - Add note to task
   251→    .post(
   252→      '/:ref/note',
   253→      async ({ params, body, error: errorResponse, projectContext }) => {
   254→        // AC: @multi-directory-daemon ac-1, ac-24 - Use project context from middleware
   255→        const ctx = await initContext(projectContext.path);
   256→        const tasks = await loadAllTasks(ctx);
   257→        const items = await loadAllItems(ctx);
   258→        const index = new ReferenceIndex(tasks, items);
   259→
   260→        // Resolve ref
   261→        const result = index.resolve(params.ref);
   262→        if (!result.ok) {
   263→          return errorResponse(404, {
   264→            error: 'not_found',
   265→            message: `Task reference "${params.ref}" not found`,
   266→          });
   267→        }
   268→
   269→        const task = tasks.find((t) => t._ulid === result.ulid);
   270→        if (!task) {
   271→          return errorResponse(404, {
   272→            error: 'not_found',
   273→            message: `Reference "${params.ref}" is not a task`,
   274→          });
   275→        }
   276→
   277→        // AC: @trait-api-endpoint ac-3 - Validate body
   278→        if (!body.content || typeof body.content !== 'string') {
   279→          return errorResponse(400, {
   280→            error: 'validation_error',
   281→            details: [
   282→              {
   283→                field: 'content',
   284→                message: 'Content is required and must be a string',
   285→              },
   286→            ],
   287→          });
   288→        }
   289→
   290→        // AC: @api-contract ac-7 - Append note
   291→        const author = getAuthor(ctx.config?.identity?.author);
   292→        const note = createNote(body.content, author);
   293→
   294→        const updatedTask: LoadedTask = {
   295→          ...task,
   296→          notes: [...(task.notes || []), note],
   297→        };
   298→
   299→        // AC: @api-contract ac-7, @trait-api-endpoint ac-5 - Shadow commit
   300→        await saveTask(ctx, updatedTask);
   301→        await commitIfShadow(ctx.shadow, `task: add note to ${params.ref}`);
   302→
   303→        // AC: @api-contract ac-7 - WebSocket broadcast
   304→        // AC: @multi-directory-daemon ac-18 - Broadcast scoped to request project
   305→        pubsub.broadcast('tasks:updates', 'task_updated', {
   306→          ref: params.ref,
   307→          ulid: task._ulid,
   308→          action: 'note_added',
   309→          note_ulid: note._ulid,
   310→        }, projectContext.path);
   311→
   312→        return {
   313→          success: true,
   314→          note,
   315→          task: updatedTask,
   316→        };
   317→      },
   318→      {
   319→        params: t.Object({
