    97→      WEB_UI_DIR: WEB_UI_BUILD,
    98→    };
    99→
   100→    // Copy E2E test fixtures to .kspec subdirectory (simulating shadow worktree mode)
   101→    if (existsSync(E2E_FIXTURES)) {
   102→      cpSync(E2E_FIXTURES, kspecDir, {
   103→        recursive: true,
   104→        filter: (src) => !src.includes('test-base') && !src.includes('project-tests')
   105→      });
   106→    } else {
   107→      throw new Error(`E2E test fixtures not found at ${E2E_FIXTURES}`);
   108→    }
   109→
   110→    // Copy project-level tests directory for AC coverage scanning
   111→    const projectTests = join(E2E_FIXTURES, 'project-tests');
   112→    if (existsSync(projectTests)) {
   113→      cpSync(projectTests, join(tempDir, 'tests'), { recursive: true });
   114→    }
   115→
   116→    // Initialize git repo in project root (required for kspec)
   117→    execSync('git init', { cwd: tempDir, stdio: 'ignore' });
   118→    execSync('git config user.email "test@test.com"', { cwd: tempDir, stdio: 'ignore' });
   119→    execSync('git config user.name "Test"', { cwd: tempDir, stdio: 'ignore' });
   120→
   121→    // Set up shadow worktree simulation for kspec to detect .kspec/ as spec directory
   122→    const gitWorktreesDir = join(tempDir, '.git', 'worktrees', '-kspec');
   123→    mkdirSync(gitWorktreesDir, { recursive: true });
   124→    writeFileSync(join(kspecDir, '.git'), `gitdir: ${gitWorktreesDir}\n`);
   125→    writeFileSync(join(gitWorktreesDir, 'gitdir'), `${join(tempDir, '.git')}\n`);
   126→    writeFileSync(join(gitWorktreesDir, 'HEAD'), 'ref: refs/heads/kspec-meta\n');
   127→
   128→    // Verify web UI is built (daemon serves it for E2E tests)
   129→    if (!existsSync(WEB_UI_BUILD)) {
   130→      throw new Error(
   131→        `Web UI not built. Run 'npm run build -w packages/web-ui' first.\n` +
   132→        `Expected build at: ${WEB_UI_BUILD}`
   133→      );
   134→    }
   135→
   136→    // Start daemon on ephemeral port with isolated HOME
   137→    const startResult = spawnSync(
   138→      'kspec',
   139→      ['serve', 'start', '--daemon', '--port', String(port), '--kspec-dir', tempDir],
   140→      {
   141→        cwd: tempDir,
   142→        encoding: 'utf-8',
   143→        env: isolatedEnv,
   144→      }
   145→    );
   146→
   147→    if (startResult.status !== 0) {
   148→      throw new Error('Failed to start daemon: ' + startResult.stderr);
   149→    }
   150→
   151→    // Wait for daemon to be ready by polling health endpoint
   152→    const maxAttempts = 30;
   153→    const pollInterval = 100;
   154→    for (let i = 0; i < maxAttempts; i++) {
   155→      try {
   156→        const response = await fetch(`${baseUrl}/api/health`);
   157→        if (response.ok) break;
   158→      } catch {
   159→        // Daemon not ready yet
   160→      }
   161→      if (i === maxAttempts - 1) {
   162→        throw new Error(`Daemon failed to become ready after ${maxAttempts * pollInterval}ms`);
   163→      }
   164→      await new Promise((r) => setTimeout(r, pollInterval));
   165→    }
   166→
   167→    // Helper to create a valid second project for multi-project tests
   168→    // AC: @multi-directory-daemon ac-25 - Tests need multiple valid projects
   169→    async function createSecondProject(): Promise<string> {
   170→      const secondProjectPath = tempDir + '-second';
   171→      const secondKspecDir = join(secondProjectPath, '.kspec');
   172→
   173→      mkdirSync(secondKspecDir, { recursive: true });
   174→
   175→      writeFileSync(
   176→        join(secondKspecDir, 'kynetic.yaml'),
   177→        `kynetic: "1.0"
   178→project: Second Test Project
   179→`
   180→      );
   181→
   182→      writeFileSync(
   183→        join(secondKspecDir, 'project.tasks.yaml'),
   184→        `# Tasks for second test project
   185→tasks: []
   186→`
   187→      );
   188→
   189→      execSync('git init', { cwd: secondProjectPath, stdio: 'ignore' });
   190→      execSync('git config user.email "test@test.com"', { cwd: secondProjectPath, stdio: 'ignore' });
   191→      execSync('git config user.name "Test"', { cwd: secondProjectPath, stdio: 'ignore' });
   192→
   193→      const gitWorktreesDir = join(secondProjectPath, '.git', 'worktrees', '-kspec');
   194→      mkdirSync(gitWorktreesDir, { recursive: true });
   195→      writeFileSync(join(secondKspecDir, '.git'), `gitdir: ${gitWorktreesDir}\n`);
   196→      writeFileSync(join(gitWorktreesDir, 'gitdir'), `${join(secondProjectPath, '.git')}\n`);
   197→      writeFileSync(join(gitWorktreesDir, 'HEAD'), 'ref: refs/heads/kspec-meta\n');
   198→
   199→      // AC: @e2e-test-daemon-isolation ac-5 — use dynamic port
   200→      const response = await fetch(`${baseUrl}/api/projects`, {
   201→        method: 'POST',
   202→        headers: { 'Content-Type': 'application/json' },
   203→        body: JSON.stringify({ path: secondProjectPath }),
   204→      });
   205→
   206→      if (!response.ok) {
   207→        const error = await response.text();
   208→        throw new Error(`Failed to register second project: ${error}`);
   209→      }
   210→
   211→      return secondProjectPath;
   212→    }
   213→
   214→    // AC: @e2e-test-daemon-isolation ac-5 — propagate port/URLs to all tests
   215→    await use({ tempDir, kspecDir, port, baseUrl, wsUrl, createSecondProject });
   216→
   217→    // AC: @e2e-test-daemon-isolation ac-4 — scoped cleanup via serve stop, not process killing
   218→    spawnSync('kspec', ['serve', 'stop', '--kspec-dir', tempDir], {
   219→      cwd: tempDir,
   220→      encoding: 'utf-8',
   221→      env: isolatedEnv,
   222→    });
   223→    await new Promise((r) => setTimeout(r, 500));
   224→
   225→    // Remove temp directories
   226→    try {
   227→      rmSync(tempDir, { recursive: true, force: true });
   228→      rmSync(tempDir + '-second', { recursive: true, force: true });
   229→    } catch {
   230→      // Best effort cleanup
   231→    }
   232→  }, { scope: 'test' }],
   233→});
   234→
   235→export { expect };
   236→
