file.content:
// Compute task counts
const tasks = tasksResponse.items;
const newCounts: TaskCounts = {
	ready: 0,
	in_progress: 0,
	needs_work: 0,
	pending_review: 0,
	blocked: 0,
	completed: 0,
	cancelled: 0
};

const completedRefs = new Set(
	tasks
		.filter((t) => t.status === 'completed')
		.flatMap((t) => [t._ulid, ...(t.slugs || [])])
);

const titles: Record<string, string> = {};

for (const task of tasks) {
	// Build task titles for active fleet
	if (task.slugs?.length) {
		for (const slug of task.slugs) {
			titles[`@${slug}`] = task.title;
		}
	}
	titles[`@${task._ulid}`] = task.title;

	switch (task.status) {
		case 'completed':
			newCounts.completed++;
			break;
		case 'in_progress':
			newCounts.in_progress++;
			break;
		case 'pending_review':
			newCounts.pending_review++;
			break;
		case 'blocked':
			newCounts.blocked++;
			break;
		case 'needs_work':
			newCounts.needs_work++;
			break;
		case 'cancelled':
			newCounts.cancelled++;
			break;
		case 'pending': {
			const deps = task.depends_on || [];
			const hasUnmetDeps = deps.some((dep: string) => {
				const ref = dep.startsWith('@') ? dep.slice(1) : dep;
				return !completedRefs.has(ref);
			});
			if (hasUnmetDeps) {
				// Pending tasks with unmet deps show in needs-attention,
				// not in the status summary blocked card (which counts status=blocked only)
				depBlockedCount++;
			} else {
				newCounts.ready++;
			}
			break;
		}
	}
}

counts = newCounts;
taskTitles = titles;
blockedTasks = newCounts.blocked;

