			status: 200,
			contentType: 'application/json',
			body: JSON.stringify(fixtureObservations())
		});
	});

	await page.route('**/api/validate', (route) => {
		route.fulfill({
			status: 200,
			contentType: 'application/json',
			body: JSON.stringify(fixtureValidation())
		});
